import React from "react";
import ReactDOM from "react-dom/client";
import "./styles/index.css";
import App from "./App";
import reportWebVitals from "./reportWebVitals";
import { ThemeProvider } from "./providers";
import "@fontsource/raleway";
import "@fontsource/raleway/400.css";
import "@fontsource/raleway/400-italic.css";
import "@fontsource/raleway/500.css";
import "@fontsource/raleway/500-italic.css";
import "@fontsource/raleway/600.css";
import "@fontsource/raleway/600-italic.css";
import "react-vertical-timeline-component/style.min.css";
import "react-awesome-slider/dist/styles.css";
import ReactGA from "react-ga4";

// Initialize Google Analytics with your tracking ID
const trackingId = process.env.REACT_APP_TRACKING_ID;
if (trackingId) {
  ReactGA.initialize(trackingId);
} else {
  console.error(`REACT_APP_TRACKING_ID is not defined`);
}

const root = ReactDOM.createRoot(
  document.getElementById("root") as HTMLElement
);
root.render(
  <React.StrictMode>
    <ThemeProvider>
      <App />
    </ThemeProvider>
  </React.StrictMode>
);

// Send web vitals to Google Analytics
reportWebVitals((metric) => {
  // Check if metric has a value before sending
  if (metric.value) {
    ReactGA.event({
      category: "Web Vitals",
      action: metric.name,
      value: Math.round(metric.value), // Round value for readability
      label: metric.id, // Optional: include metric id as a label
      nonInteraction: true, // Ensure this event doesn't affect bounce rate
    });
  }
});
