import { useBoolean } from "../hooks";
import ProjectDialog from "./ProjectDialog";
import { useTranslation } from "react-i18next";
import { useState } from "react";
import { ProjectType } from "../i18n/config";

const Projects = () => {
  const [isOpen, setIsOpen] = useBoolean();
  const [selectedProject, setSelectedProject] = useState<
    ProjectType | undefined
  >();
  const { t } = useTranslation();

  const handleProjectDetails = (project: ProjectType) => {
    setSelectedProject(project);
    setIsOpen.on();
  };

  const projects = t("projects.projects", {
    returnObjects: true,
  }) as ProjectType[];

  const sortedProjects = projects.sort((a, b) => {
    const dateA = new Date(a.startDate.split("-").reverse().join("-"));
    const dateB = new Date(b.startDate.split("-").reverse().join("-"));
    return dateB.getTime() - dateA.getTime();
  });

  return (
    <section className="bg-surface-light px-3 py-20 dark:bg-navy-darkest md:px-0">
      <div className="mx-auto max-w-7xl">
        <h2 className="py-10 text-center text-xl font-medium uppercase tracking-widest text-black dark:text-text-primary mb-10">
          {t("projects.title")}
        </h2>
        <div className="flex flex-wrap justify-center gap-16 reveal-stagger">
          {sortedProjects.map((item: any) => (
            <div
              className="mb-[30px] inline-block cursor-pointer bg-white p-5 text-center shadow-card transition-all duration-300 ease-linear hover:scale-105 hover:shadow-[0_0_20px_rgba(100,255,218,0.15)] dark:bg-navy-dark dark:border dark:border-accent/10"
              onClick={() => handleProjectDetails(item)}
              key={item.title}
            >
              <img
                className="relative max-h-[230px] dark:invert mx-auto"
                src={item.images[0]}
                alt="Profile"
              />
              <span className="mt-3 rounded-b-lg bg-navy-dark px-4 pb-1 pt-2 text-center text-lg text-white dark:bg-accent/10 dark:text-accent">
                {new Date(
                  item.startDate.split("-").reverse().join("-")
                ).getFullYear()}
              </span>
              <p className="font-xl mt-2 font-bold uppercase tracking-wide text-black dark:text-text-primary">
                {item.title}
              </p>
            </div>
          ))}
        </div>
      </div>
      <ProjectDialog
        open={isOpen}
        onClose={setIsOpen.off}
        project={selectedProject}
      />
    </section>
  );
};

export default Projects;
