import {
  VerticalTimeline,
  VerticalTimelineElement,
} from "react-vertical-timeline-component";
import { Icon } from "@iconify/react";
import { useTranslation } from "react-i18next";

interface BadgeProps {
  text: string;
}

const Badge = ({ text }: BadgeProps) => (
  <span className="rounded-xl bg-surface-light px-[5px] py-[2px] text-sm dark:bg-navy/60 dark:text-text-primary">
    {text}
  </span>
);

const Experience = () => {
  const { t } = useTranslation();

  const experiences = t("experience.experiences", { returnObjects: true }) as any[];
  const reversedExperiences = [...experiences].reverse();

  return (
    <section
      className="bg-surface-light px-3 py-10 pb-20 dark:bg-navy-darkest md:px-0 [--line-color:#d1d5db] dark:[--line-color:rgba(100,255,218,0.15)]"
    >
      <h2 className="py-10 text-center text-xl font-medium uppercase tracking-widest text-black dark:text-text-primary mb-10">
        {t("experience.title")}
      </h2>

      <VerticalTimeline>
        {reversedExperiences.map((exp: any) => (
          <VerticalTimelineElement
            key={exp.title}
            date={exp.years}
            dateClassName="dark:text-text-primary"
            iconClassName="bg-navy text-white dark:bg-accent/20 dark:text-accent"
            icon={<Icon icon={exp.mainTechIcon} />}
            className="dark:brightness-80 dark:filter"
          >
            <div className="flex items-center">
              <img
                src={exp.logo}
                alt={`${exp.altlogo}`}
                className="w-10 h-10 mr-4"
              />
              <div>
                <Badge text={exp.mainTech} />
                <h3 className="text-lg font-bold">{exp.title}</h3>
                <h4 className="text-md font-bold">{exp.company}</h4>
              </div>
            </div>
            <div className="mt-2 flex flex-wrap gap-2">
              {exp.technologies.map((tech: any) => (
                <Badge key={tech} text={tech} />
              ))}
            </div>
            <p className="mt-2 text-gray-600 dark:text-text-muted">
              {exp.description}
            </p>
          </VerticalTimelineElement>
        ))}
        <VerticalTimelineElement
          iconClassName="bg-navy text-white dark:bg-accent/20 dark:text-accent"
          icon={<Icon icon="eos-icons:hourglass" />}
        />
      </VerticalTimeline>
    </section>
  );
};

export default Experience;
