import { useContext, useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { Icon } from "@iconify/react";
import { TypeAnimation } from "react-type-animation";
import { ThemeContext, ThemeContextInterface } from "../providers";

const BOOT_MESSAGES = [
  "> Initializing portfolio... [OK]",
  "> Loading projects... [3 found]",
  "> Loading experience... [4 entries]",
  "> Systems operational.",
];

const Header = () => {
  const { darkTheme, toggleTheme } = useContext(
    ThemeContext
  ) as ThemeContextInterface;

  const { t, i18n } = useTranslation();
  const titles = t("basic_info.titles", { returnObjects: true }) as string[];

  const [bootIndex, setBootIndex] = useState(0);
  const [bootVisible, setBootVisible] = useState(true);

  useEffect(() => {
    if (bootIndex < BOOT_MESSAGES.length - 1) {
      const timer = setTimeout(() => {
        setBootIndex((prev) => prev + 1);
      }, 1200);
      return () => clearTimeout(timer);
    } else {
      const fadeTimer = setTimeout(() => {
        setBootVisible(false);
      }, 2000);
      return () => clearTimeout(fadeTimer);
    }
  }, [bootIndex]);

  const handleLanguageChange = (lang: string) => {
    i18n.changeLanguage(lang);
  };

  return (
    <>
      <header className="relative h-[650px] w-[100%] bg-surface-light dark:bg-navy-darkest">
        <div className="flex h-full flex-col items-center justify-center gap-5">
          <div>
            <div className="relative flex items-center justify-center">
              <div className="absolute h-[120px] w-[120px] rounded-full bg-accent/10 blur-2xl" />
              <Icon
                className="relative text-gray-dark dark:text-accent"
                icon="la:laptop-code"
                style={{
                  height: "100%",
                  fontSize: 150,
                }}
              />
            </div>
          </div>

          <h1 className="text-4xl font-bold text-navy-darkest dark:text-accent">
            {t("basic_info.name")}
          </h1>
          {titles.length > 1 ? (
            <>
            <TypeAnimation
              sequence={titles.flatMap((title) => [title, 1000])}
              wrapper="span"
              speed={50}
              className="text-regular text-2xl text-gray-dark dark:text-text-primary"
              repeat={Infinity}
            />
            <span className="animate-blink text-navy-darkest dark:text-accent text-2xl">|</span>
            </>
          ) : (
            <>
            <span className="text-regular text-2xl text-gray-dark dark:text-text-primary">
              {titles[0]}
            </span>
            <span className="animate-blink text-navy-darkest dark:text-accent text-2xl">|</span>
            </>
          )}

          <div
            className={`font-mono text-sm transition-opacity duration-700 ${
              bootVisible ? "opacity-100" : "opacity-0"
            }`}
          >
            {BOOT_MESSAGES.slice(0, bootIndex + 1).map((msg, idx) => (
              <div
                key={idx}
                className={`${
                  msg.includes("[OK]") || msg.includes("found") || msg.includes("entries")
                    ? "text-black dark:text-accent"
                    : "text-navy-darkest dark:text-text-muted"
                }`}
              >
                {msg}
              </div>
            ))}
          </div>
        </div>

        <div className="absolute top-4 right-4 flex items-center gap-4">
          <div className="flex rounded-lg border border-gray-300 dark:border-accent/30 overflow-hidden">
            <button
              onClick={() => handleLanguageChange("en")}
              className={`px-3 py-1.5 text-sm font-medium transition-all duration-200 ${
                i18n.language === "en"
                  ? "bg-accent text-navy-darkest"
                  : "bg-white dark:bg-navy-dark text-gray-dark dark:text-text-muted hover:text-navy-darkest dark:hover:text-text-primary"
              }`}
            >
              EN
            </button>
            <button
              onClick={() => handleLanguageChange("zh")}
              className={`px-3 py-1.5 text-sm font-medium transition-all duration-200 ${
                i18n.language === "zh"
                  ? "bg-accent text-navy-darkest"
                  : "bg-white dark:bg-navy-dark text-gray-dark dark:text-text-muted hover:text-navy-darkest dark:hover:text-text-primary"
              }`}
            >
              中文
            </button>
          </div>

          <button
            onClick={toggleTheme}
            className="relative flex h-10 w-20 items-center rounded-full border border-gray-300 dark:border-accent/30 bg-white dark:bg-navy-dark transition-colors duration-300 focus:outline-none focus:ring-2 focus:ring-accent/50"
            aria-label="Toggle theme"
          >
            <div
              className={`absolute flex h-8 w-8 items-center justify-center rounded-full bg-accent shadow-[0_0_10px_rgba(100,255,218,0.4)] transition-transform duration-300 ${
                darkTheme ? "translate-x-11" : "translate-x-1"
              }`}
            >
              <Icon
                icon={darkTheme ? "ic:outline-light-mode" : "ic:outline-dark-mode"}
                className="text-navy-darkest text-lg"
              />
            </div>
          </button>
        </div>
      </header>
    </>
  );
};

export default Header;
